function biggestByParitySwaps(num: number): number {
  const d = String(num).split("").map(Number);
  for (let i = 0; i < d.length; i++) {
    let best = i;
    for (let j = i + 1; j < d.length; j++)
      if (d[j] % 2 === d[i] % 2 && d[j] > d[best]) best = j;
    [d[i], d[best]] = [d[best], d[i]];
  }
  return Number(d.join(""));
}

