class Solution:
    def biggestByParitySwaps(self, num: int) -> int:
        d = [int(c) for c in str(num)]
        for i in range(len(d)):
            best = i
            for j in range(i + 1, len(d)):
                if d[j] % 2 == d[i] % 2 and d[j] > d[best]:
                    best = j
            d[i], d[best] = d[best], d[i]
        return int("".join(map(str, d)))

