function biggestByParitySwaps(num: number): number {
  const d = String(num).split("").map(Number);
  const odd = d.filter(x => x % 2 === 1).sort((a, b) => b - a);
  const even = d.filter(x => x % 2 === 0).sort((a, b) => b - a);
  let oi = 0, ei = 0;
  const out = d.map(x => (x % 2 === 1 ? odd[oi++] : even[ei++]));
  return Number(out.join(""));
}

