        d = [int(c) for c in str(num)]
        odd = iter(sorted((x for x in d if x % 2), reverse=True))
        even = iter(sorted((x for x in d if x % 2 == 0), reverse=True))
        return int("".join(str(next(odd) if x % 2 else next(even)) for x in d))

